import { useCallback,useEffect,useMemo,useRef,useState,useSyncExternalStore,type FormEvent,type PointerEvent as ReactPointerEvent,type ReactNode } from 'react';
import type { User } from '@supabase/supabase-js';
import {
  Activity, AlarmClock, ArrowDown, ArrowLeft, ArrowRight, Bell, BookOpen, CalendarDays, Check, CheckCircle2,
  Clock3, Cloud, CloudOff, Download, FileJson, Flag, LayoutGrid, ListTodo, LogOut, Menu, Moon,
  Plus, RefreshCw, Settings2, ShieldCheck, Upload, X, XCircle
} from 'lucide-react';
import type { Category, FlexibleTask, Preferences, ScheduleEvent, SessionLog, SessionStatus } from './domain/types';
import { CATEGORIES } from './domain/types';
import { dateAddDays,formatDateLabel,formatClock,isValidTimezone,minutesToTime,nowAtZone,timeInZone,timeToMinutes,weekdayOf } from './domain/time';
import { expandEvents,moveRecurringOccurrence } from './domain/recurrence';
